
const DEFAULT_D=[[.2,.2,.4],[.2,.2,.6],[.2,.4,.2],[.2,.4,.4],[.2,.6,.2],[.4,.2,.4],[.4,.4,.2]],ids=DEFAULT_D.map((_,i)=>'A0'+(i+1)),pages=['Tổng quan','Thiết kế & DOE','Thực nghiệm','Phân tích','COMSOL','Xuất dữ liệu','Nội bộ cấu hình','Chi tiết mẫu','Hình học & tối ưu'];let state=JSON.parse(localStorage.getItem('capstone-v1')||'{}');state.samples??={};state.mesh??={};state.settings??={step1:'',step2:'',peak:'',detect:'',recover:'',drift:''};let page=0,di=0,si=1,test=0,mi=0,stage=0,mode='guide',timerId=null;const save=()=>localStorage.setItem('capstone-v1',JSON.stringify(state)), key=()=>ids[di]+'-0'+si, sample=(k=key())=>state.samples[k]??=( {made:false,r0:'',tn1:[],tn2:[],notes:''}), all=()=>ids.flatMap(id=>[1,2,3].map(n=>sample(id+'-0'+n))), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), val=x=>x!==''&&x!=null&&Number.isFinite(+x), fmt=x=>Number.isFinite(x)?x.toPrecision(5):'—';function go(n){page=n;render()}function geom(i){const [b,t,w]=doeRows()[i],h=b+t+w,k=125,base=180,top=base-h*k,ct=base-(b+w)*k,cb=base-b*k,l=155-w*k/2,r=155+w*k/2;const f=n=>String(+n.toFixed(6));const line=(x1,y1,x2,y2,c='#64748b')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c}" stroke-width=".9"/>`;const dim=(x,y1,y2,label,from1,from2)=>`${line(from1,y1,x+6,y1)}${line(from2,y2,x+6,y2)}${line(x,y1,x,y2,'#17365d')}<path d="M${x-3} ${y1+5} L${x} ${y1} L${x+3} ${y1+5} M${x-3} ${y2-5} L${x} ${y2} L${x+3} ${y2-5}" fill="none" stroke="#17365d"/><text x="${x+8}" y="${(y1+y2)/2+4}" font-size="10" fill="#17365d">${label}</text>`;return `<svg viewBox="0 0 420 245" role="img" aria-label="Mặt cắt ngang ${ids[i]} có kích thước" style="width:100%;max-width:520px"><rect x="65" y="${top}" width="180" height="${h*k}" fill="#d4e8ef" stroke="#315777" stroke-width="1.5"/><rect x="${l}" y="${ct}" width="${w*k}" height="${w*k}" fill="#64748b" stroke="#334155" stroke-width="1.3"/>${dim(258,top,ct,'tt '+f(t),245,r)}${dim(258,ct,cb,'hc '+f(w),r,r)}${dim(258,cb,base,'tb '+f(b),r,245)}${dim(17,top,base,'Hs '+f(h),65,65)}${line(l,cb,l,203)}${line(r,cb,r,203)}${line(l,198,r,198,'#17365d')}<path d="M${l+5} 195 L${l} 198 L${l+5} 201 M${r-5} 195 L${r} 198 L${r-5} 201" fill="none" stroke="#17365d"/><text x="155" y="214" text-anchor="middle" font-size="11">wc = ${f(w)} mm</text><text x="155" y="232" text-anchor="middle" font-size="10" fill="#607487">Mặt cắt y–z · chiều rộng khối thu gọn</text><path d="M350 180 V150 M350 180 H380 M347 155 L350 150 L353 155 M375 177 L380 180 L375 183" fill="none" stroke="#334155"/><text x="346" y="145" font-size="11">z</text><text x="385" y="184" font-size="11">y</text></svg>`}
function geometryPanel(i){let [b,t,w]=doeRows()[i];return `<div class="geometry-pair"><div>${geom(i)}<small>Silicone: xanh nhạt · kim loại lỏng: xám. Kích thước mm; tỷ lệ theo chiều dày và vi kênh được giữ nguyên.</small></div><div class="scroll"><table><tr><th>Ký hiệu</th><th>mm</th><th>Giới hạn đo</th></tr>${[['tt',t,'Mặt trên silicone → trần kênh'],['hc',w,'Trần → đáy kênh'],['tb',b,'Đáy kênh → mặt dưới silicone'],['Hs',b+t+w,'Mặt trên → mặt dưới silicone'],['wc',w,'Thành trái → thành phải kênh']].map(([n,v,d])=>`<tr><td><strong>${n}</strong></td><td>${+v.toFixed(6)}</td><td style="text-align:left">${d}</td></tr>`).join('')}</table><p><strong>Hs = tb + hc + tt</strong></p></div></div>`}
function doeRows(){return DEFAULT_D.map((r,i)=>state.doe?.[ids[i]]||r)}
function geo(k){return state.geometry?.[k]??({Ls:50,Ws:10,Dp:5,xp:25,yp:5,Lc:50})[k]}
function hasMeasured(i){return [1,2,3].some(n=>{let v=state.samples[ids[i]+'-0'+n];return v&&(v.made||val(v.r0)||v.tn1?.length||v.tn2?.length)})}
function meshExists(){return Object.values(state.mesh||{}).some(v=>Array.isArray(v)?v.length:!!v)}
function editDOE(i){let r=[0,1,2].map(j=>Number(document.getElementById('doe-'+i+'-'+j).value));let [b,t,w]=r;if(!r.every(Number.isFinite)||Math.min(...r)<.2||t+w<.5-1e-9||b+t+w>1+1e-9)return alert('Không thỏa ràng buộc: tb, tt, wc ≥ 0.2 mm; tt + hc ≥ 0.5 mm; Hs ≤ 1 mm.');if(r.every((v,j)=>v===doeRows()[i][j]))return;if(hasMeasured(i)||meshExists())return alert('Đã có mẫu chế tạo, dữ liệu đo hoặc FEM. Không đổi hình học để tránh gán sai dữ liệu.');state.doe??={};state.doe[ids[i]]=r;save();render()}
function editGeo(){let keys=['Ls','Ws','Dp','xp','yp','Lc'],v=Object.fromEntries(keys.map(k=>[k,Number(document.getElementById('geo-'+k).value)]));if(!Object.values(v).every(x=>Number.isFinite(x)&&x>0)||v.Lc>v.Ls||v.Ws<Math.max(...doeRows().map(r=>r[2]))||v.xp-v.Dp/2<0||v.xp+v.Dp/2>v.Ls||v.yp-v.Dp/2<0||v.yp+v.Dp/2>v.Ws)return alert('Kiểm tra kích thước dương, Lc ≤ Ls, đầu nén nằm trong khối và chiều rộng kênh.');if(keys.every(k=>v[k]===geo(k)))return;if(ids.some((_,i)=>hasMeasured(i))||meshExists())return alert('Đã có dữ liệu nghiên cứu. Không đổi thông số chung để tránh gán sai dữ liệu.');state.geometry=v;save();render()}
function localPairs(){let d=doeRows(),p=[];for(let i=0;i<d.length;i++)for(let j=i+1;j<d.length;j++){let k=[0,1,2].filter(k=>Math.abs(d[i][k]-d[j][k])>1e-9);if(k.length===1){let z=k[0];p.push([i,j,['tb','tt','wc'][z],d[j][z]-d[i][z]])}}return p}
function doe(){return `<section><h2>Thông số hình học và vị trí đo</h2><div class="geometry-pair"><div><svg viewBox="0 0 420 200" style="width:100%" role="img" aria-label="Hình chiếu bằng cảm biến"><rect x="45" y="55" width="300" height="60" fill="#d4e8ef" stroke="#315777"/><path d="M45 85 H345" stroke="#64748b" stroke-dasharray="4 3"/><circle cx="195" cy="85" r="15" fill="#ffffff" fill-opacity=".6" stroke="#17365d"/><path d="M45 50 V30 M345 50 V30 M45 35 H345 M350 55 H375 M350 115 H375 M370 55 V115 M45 120 V145 M195 102 V145 M45 140 H195 M195 85 H365 M360 55 V85" stroke="#64748b" fill="none"/><text x="195" y="28" text-anchor="middle" font-size="12">Ls = ${geo("Ls")} mm</text><text x="378" y="88" font-size="11">Ws</text><text x="120" y="155" text-anchor="middle" font-size="11">xp = ${geo("xp")} mm</text><text x="363" y="72" font-size="10">yp</text><path d="M180 85 H210 M210 85 L250 165" stroke="#17365d" fill="none"/><text x="252" y="169" font-size="11">Dp = ${geo("Dp")} mm</text><text x="45" y="185" font-size="11">Hình chiếu bằng x–y · kênh nét đứt</text></svg></div><div class="scroll"><table><tr><th>Ký hiệu</th><th>mm</th><th>Ý nghĩa</th></tr>${[['Ls',geo('Ls'),'Chiều dài khối'],['Ws',geo('Ws'),'Chiều rộng khối'],['Dp',geo('Dp'),'Đường kính đầu nén'],['xp',geo('xp'),'Từ đầu trái đến tâm đầu nén'],['yp',geo('yp'),'Từ cạnh trên hình đến tâm đầu nén'],['Lc',geo('Lc'),'Chiều dài dẫn điện danh nghĩa, cần xác nhận']].map(([n,v,d])=>`<tr><td>${n}</td><td><input id="geo-${n}" type="number" step="any" min="0" value="${v}"></td><td style="text-align:left">${d}</td></tr>`).join('')}</table><button class="primary" onclick="editGeo()">Lưu thông số chung</button><p class="muted">Hình chiếu bằng minh họa, không theo tỷ lệ.</p></div></div></section><section><h2>Ma trận DOE · mm</h2><p class="muted">Sửa ba biến độc lập rồi lưu từng hàng. Hs và S₀ tự tính. Khóa thay đổi khi đã chế tạo hoặc đo mẫu liên quan, hoặc có FEM.</p><div class="scroll"><table><tr><th>ID</th><th>tb</th><th>tt</th><th>wc = hc</th><th>Hs</th><th>A₀ (mm²)</th><th>Thao tác</th></tr>${doeRows().map(([b,t,w],i)=>`<tr><td>${ids[i]}</td>${[b,t,w].map((v,j)=>`<td><input id="doe-${i}-${j}" type="number" step="any" min="0.2" value="${v}"></td>`).join('')}<td>${+(b+t+w).toFixed(6)}</td><td>${+(w*w).toFixed(6)}</td><td><button onclick="editDOE(${i})">Lưu</button></td></tr>`).join('')}</table></div></section>${doeRows().map((_,i)=>`<section><h2>${ids[i]} · Mặt cắt ngang</h2>${geometryPanel(i)}</section>`).join('')}`}
function set(k,v){sample()[k]=v;save();render()}function setting(k,v){if(k==='step1'&&all().some(s=>s.tn1.length)&&String(v)!==String(state.settings.step1)){alert('Bước tải đã được sử dụng; giữ nguyên để so sánh các mẫu.');render();return}state.settings[k]=v;save();render()}function cell(a,i,k,v){sample()[a][i][k]=v;save()}function add(a){if(sample()[a].length<100){sample()[a].push({});save();render()}}function regression(){let p=[];ids.forEach((id,i)=>[1,2,3].forEach(n=>{let r=sample(id+'-0'+n).r0;if(val(r)&&+r>0)p.push([(geo("Lc")*1000)/(doeRows()[i][2]**2),+r])}));if(p.length!==21)return null;let x=p.reduce((s,a)=>s+a[0],0)/21,y=p.reduce((s,a)=>s+a[1],0)/21,m=p.reduce((s,a)=>s+(a[0]-x)*(a[1]-y),0)/p.reduce((s,a)=>s+(a[0]-x)**2,0);return Number.isFinite(m)?[m,y-m*x]:null}function render(){document.querySelector('#nav').innerHTML=pages.map((p,i)=>`<button class="${i===page?'active':''}" onclick="go(${i})">${p}</button>`).join('');document.querySelector('#title').textContent=pages[page];let s=sample(),a=all(),r=regression(),html='';if(page===0){html=`<div class="grid">${[['Cấu hình',7],['Chế tạo',a.filter(x=>x.made).length+'/21'],['TN0',a.filter(x=>val(x.r0)&&+x.r0>0).length+'/21'],['Điện trở suất',r?fmt(r[0]):'—']].map(([k,v])=>`<div class="tile"><small>${k}</small><div class="num">${v}</div></div>`).join('')}</div><section><h2>Tiến độ theo cấu hình</h2><table><tr><th>ID</th><th>Chế tạo</th><th>TN0</th><th>TN1 có dữ liệu</th><th>TN2 có dữ liệu</th></tr>${ids.map((id,i)=>{let b=[1,2,3].map(n=>sample(id+'-0'+n));return `<tr><td><button onclick="di=${i};go(2)">${id}</button></td>${[b.filter(x=>x.made).length,b.filter(x=>val(x.r0)&&+x.r0>0).length,b.filter(x=>x.tn1.some(y=>val(y.peak)&&val(y.after))).length,b.filter(x=>x.tn2.some(y=>val(y.r))).length].map(n=>`<td>${n}/3<progress value="${n}" max="3"></progress></td>`).join('')}</tr>`}).join('')}</table></section>`}if(page===1)html=doe();if(page===2){html=`<section><div class="bar"><select onchange="di=+this.value;render()">${ids.map((id,i)=>`<option value="${i}" ${di===i?'selected':''}>${id}</option>`).join('')}</select><select onchange="si=+this.value;render()">${[1,2,3].map(n=>`<option ${si===n?'selected':''}>${n}</option>`).join('')}</select><label><span>Đã chế tạo</span><input type="checkbox" ${s.made?'checked':''} onchange="set('made',this.checked)"></label></div>${geom(di)}<div class="bar">${['TN0','TN1','TN2'].map((t,i)=>`<button class="${test===i?'primary':''}" onclick="test=${i};render()">${t}</button>`).join('')}</div></section>`;if(test===0)html+=`<section><h2>Điện trở không tải</h2><p>F = 0 N. Chờ ổn định trước khi ghi nhận.</p><label>R₀ (Ω)<input type="number" min="0" step="any" value="${esc(s.r0)}" onchange="set('r0',this.value)"></label></section>`;if(test===1)html+=`<section><h2>TN1 · Dải đo</h2><p>Tăng tải đến đỉnh, đo Rpeak, nhả hoàn toàn và đo Rafter sau thời gian phục hồi.</p><label>ΔF danh nghĩa (N)<input type="number" step="any" value="${esc(state.settings.step1)}" onchange="setting('step1',this.value)"></label><div class="scroll"><table><tr><th>Lần</th><th>F (N)</th><th>Rbefore (Ω)</th><th>Rpeak (Ω)</th><th>Rafter (Ω)</th><th>Ghi chú</th></tr>${s.tn1.map((x,i)=>`<tr><td>${i+1}</td><td>${+state.settings.step1>0?fmt((i+1)*+state.settings.step1):'—'}</td><td>${esc(i?s.tn1[i-1].after:s.r0)}</td>${['peak','after','note'].map(k=>`<td><input ${k==='note'?'':'type="number" step="any"'} value="${esc(x[k])}" onchange="cell('tn1',${i},'${k}',this.value);render()"></td>`).join('')}</tr>`).join('')}</table></div><p><button class="primary" onclick="add('tn1')">+ Mức tải</button></p></section>`;if(test===2)html+=`<section><h2>TN2 · Đường đặc tính</h2><p>Nhập lực danh nghĩa và điện trở đo trên hai nhánh nén, nhả.</p><table><tr><th>Nhánh</th><th>F (N)</th><th>R (Ω)</th></tr>${s.tn2.map((x,i)=>`<tr><td><select onchange="cell('tn2',${i},'branch',this.value)"><option>Nén</option><option ${x.branch==='Nhả'?'selected':''}>Nhả</option></select></td>${['f','r'].map(k=>`<td><input type="number" step="any" value="${esc(x[k])}" onchange="cell('tn2',${i},'${k}',this.value)"></td>`).join('')}</tr>`).join('')}</table><p><button class="primary" onclick="add('tn2')">+ Điểm đo</button></p></section>`}if(page===2)html=lab();if(page===3)html=`<section><h2>Hồi quy điện trở suất</h2><p>R₀ = ρ Lc/A₀ + Rp · Lc = ${geo("Lc")} mm (danh nghĩa)</p><div class="grid"><div class="tile"><small>ρ (Ω·m)</small><div class="num">${r?fmt(r[0]):'—'}</div></div><div class="tile"><small>Rp (Ω)</small><div class="num">${r?fmt(r[1]):'—'}</div></div></div><p>${r?'Kiểm tra giả định điện trở ký sinh đồng nhất.':'Cần đủ 21 giá trị R₀ dương.'}</p><p class="muted">Các chỉ tiêu dải đo, độ nhạy, độ trễ, tuyến tính và Pareto chưa được triển khai trong prototype này.</p></section>`;if(page===3)html=analysis25();if(page===4){let m=state.mesh[mi]??=[];html=`<section><h2>Ba cấp độ lưới</h2><select onchange="mi=+this.value;render()">${['M01 – Coarse','M02 – Medium','M03 – Fine'].map((v,i)=>`<option value="${i}" ${mi===i?'selected':''}>${v}</option>`).join('')}</select><p>Dán tối đa 100 dòng TSV từ COMSOL theo thứ tự s, δ (mm), F (N), Scenter (mm²), R (Ω).</p><textarea id="paste" rows="6" style="width:100%;border:1px solid #bdcbd8"></textarea><p><button class="primary" onclick="importMesh()">Nhập dữ liệu</button></p><table><tr>${['s','δ (mm)','F (N)','Scenter (mm²)','R (Ω)'].map(x=>`<th>${x}</th>`).join('')}</tr>${m.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</table><p class="muted">Đánh giá hội tụ đường cong chưa được triển khai.</p></section>`}if(page===5)html=`<section><h2>Sao lưu dữ liệu</h2><button class="primary" onclick="download()">Xuất JSON</button><p>File JSON chứa toàn bộ dữ liệu cục bộ để lưu trữ.</p></section>`;if(page===5)html=exportCenter();if(page===6)html=internal26();if(page===7)html=sample26();if(page===8)html=geometry26();if(page===4)html+=fem25();document.querySelector('#view').innerHTML=html}function importMesh(){let rows=document.querySelector('#paste').value.trim().split(/\r?\n/).map(x=>x.trim().split(/\t+/).map(Number));if(rows.length>100||rows.some(x=>x.length!==5||x.some(v=>!Number.isFinite(v))))return alert('Cần 5 cột số, tối đa 100 dòng.');if(state.mesh[mi]?.length&&!confirm('Thay thế dữ liệu lưới hiện tại?'))return;state.mesh[mi]=rows;save();render()}function download(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='capstone-backup.json';a.click();URL.revokeObjectURL(a.href)}
const protocols=[[
['Chuẩn bị','Đặt mẫu trên mặt đỡ, kiểm tra điện cực và đưa đầu nén ra khỏi mẫu.','Loại bỏ tải cơ học khỏi phép đo điện trở ban đầu.'],['Ổn định','Chờ điện trở ổn định theo điều kiện đo đã thống nhất.','Tránh ghi nhận dao động tức thời của thiết bị.'],['Ghi R₀','Nhập điện trở dương đo được tại F = 0 N.','R₀ là mốc chuẩn và dữ liệu hồi quy điện trở suất.']],[
['Chuẩn bị','Căn tâm đầu nén tại x = 25 mm, y = 5 mm. Kiểm tra điểm zero của đồng hồ lực.','Giữ vị trí tải nhất quán giữa các mẫu.'],['Trước nén','Kiểm tra trạng thái không tải. Nếu phép thử gián đoạn, đo lại Rbefore.','Tạo mốc tham chiếu đúng cho chu kỳ.'],['Tăng tải','Tăng đến lực danh nghĩa hiển thị. Giữ tải theo thời gian quy định.','Tạo biến dạng cục bộ có kiểm soát.'],['Đo đỉnh','Ghi Rpeak tại cuối thời gian giữ tải.','Định lượng tín hiệu điện do biến dạng.'],['Nhả tải','Nhả hoàn toàn, chờ thời gian phục hồi rồi ghi Rafter.','Đánh giá khả năng phục hồi sau tải.'],['Đánh giá','Kiểm tra mất tín hiệu, hư hỏng, bão hòa và sai lệch phục hồi trước khi tăng tải.','Ghi nhận hiện tượng thực tế để phân tích sau.']],[
['Chuẩn bị','Xác nhận dải tải chung FL–FU, bước tải và thời gian giữ tải. Sử dụng R₀ từ TN0.','Tạo điều kiện so sánh công bằng giữa các mẫu.'],['Nhánh nén','Tăng tải theo bậc từ FL đến FU. Ghi R sau thời gian giữ tại mỗi bậc. Không nhả về zero giữa các bậc.','Xây dựng đường đặc tính khi tăng tải.'],['Nhánh nhả','Giảm tải theo các bậc tương ứng từ FU về FL, ghi R tại từng bậc.','So sánh hai nhánh tại cùng lực để xác định độ trễ.'],['Phục hồi','Nhả hoàn toàn về zero, chờ phục hồi và ghi điện trở cuối.','Kiểm tra sự thay đổi điện trở sau toàn bộ chu kỳ.']]];
const labels={step1:'Bước tải TN1 (N)',step2:'Bước tải TN2 (N)',peak:'Thời gian giữ tải (s)',wait:'Thời gian phục hồi (s)',detect:'Ngưỡng phát hiện ΔR (Ω)',recover:'Sai lệch phục hồi cho phép (%)',drift:'Drift cho phép (%)',safe:'Giới hạn tải an toàn (N)',fl:'FL chung (N)',fu:'FU chung (N)'};
const hints={"step1": "Lực tăng giữa hai chu kỳ; > 0 N, phù hợp độ phân giải lực.", "step2": "Khoảng cách giữa hai bậc tải TN2; > 0 N.", "peak": "Thời gian duy trì lực trước khi đọc R; > 0 s.", "wait": "Thời gian chờ sau nhả hoàn toàn; > 0 s.", "detect": "Biên độ điện trở nhỏ nhất nhận biết được; > 0 Ω, căn cứ thiết bị.", "recover": "Sai lệch so với Rbefore tối đa; ≥ 0%.", "drift": "Sai lệch tích lũy so với R₀ TN0 tối đa; ≥ 0%.", "safe": "Tùy chọn; nếu nhập phải dương và ≥ bước tải TN1. Luôn tuân thủ giới hạn an toàn thực tế.", "fl": "Cận dưới dải chung đã xác nhận; ≥ 0 N.", "fu": "Cận trên dải chung đã xác nhận; > FL và không vượt tải an toàn."};
function field(label,value,handler,hint='',type='number'){return `<label class="field">${label}<input type="${type}" ${type==='number'?'step="any" min="0"':''} value="${esc(value)}" onchange="${handler}"><small>${hint}</small></label>`}
function diagram(){let loaded=test===1&&[2,3].includes(stage)||test===2&&[1,2].includes(stage);return `<div class="diagram"><svg viewBox="0 0 360 205" role="img" aria-label="Mặt cắt dọc cảm biến và đầu nén"><defs><linearGradient id="steel"><stop stop-color="#718096"/><stop offset=".5" stop-color="#e2e8f0"/><stop offset="1" stop-color="#718096"/></linearGradient></defs><rect x="132" y="8" width="96" height="30" rx="5" fill="#17365d"/><text x="180" y="27" fill="white" text-anchor="middle" font-size="11">Đồng hồ lực</text><rect x="175" y="38" width="10" height="${loaded?43:25}" fill="#64748b"/><rect x="145" y="${loaded?81:63}" width="70" height="24" rx="2" fill="url(#steel)" stroke="#475569"/><path d="${loaded?'M40 99 H140 Q180 111 220 99 H320 V145 H40Z':'M40 99 H320 V145 H40Z'}" fill="#bcdbe9" stroke="#41677d"/><path d="${loaded?'M40 117 H140 Q180 127 220 117 H320 V129 H220 Q180 130 140 129 H40Z':'M40 117 H320 V129 H40Z'}" fill="#64748b"/><rect x="30" y="145" width="300" height="10" fill="#475569"/><path d="M40 123 H15 V181 H130 M320 123 H345 V181 H230" stroke="#b45309" stroke-width="2" fill="none"/><rect x="130" y="166" width="100" height="30" rx="4" fill="#17365d"/><text x="180" y="185" text-anchor="middle" fill="white" font-size="12">R (Ω)</text><text x="238" y="76" font-size="11" fill="#17365d">${loaded?'F ↓':'F = 0'}</text><text x="45" y="111" font-size="10">Silicone</text><text x="235" y="140" font-size="10">Vi kênh</text></svg><small>Minh họa cơ chế, không theo tỷ lệ và không phải kết quả FEM.</small></div>`}
function setStage(n){stage=n;render()}function startTimer(k){clearInterval(timerId);let n=+(test===1?sample().tn1.at(-1)?.conditions?.[k]??state.settings[k]:state.settings[k]);if(!val(state.settings[k])||n<0)return alert('Thiết lập thời gian trước.');let end=Date.now()+n*1000;const tick=()=>{let el=document.getElementById('clock');if(!el){clearInterval(timerId);return}let left=Math.max(0,Math.ceil((end-Date.now())/1000));el.textContent=left?left+' s':'Hết thời gian';if(!left)clearInterval(timerId)};tick();timerId=setInterval(tick,200)}
function positive(v){return val(v)&&Number.isFinite(+v)&&+v>0}
function tn1metrics(x,i,s){let raw=val(x.before)?x.before:i?s.tn1[i-1].after:(s.r0),b=positive(raw)?+raw:NaN,r0=x.conditions?.r0||s.r0,dr=positive(x.peak)&&positive(b)?+x.peak-b:NaN,rec=positive(x.after)&&positive(b)?100*Math.abs(+x.after-b)/b:NaN,drift=positive(r0)&&positive(x.after)?100*Math.abs(+x.after-+r0)/+r0:NaN;let flags=['loss','damage','saturation'].filter(k=>x[k]).map(k=>({loss:'Mất tín hiệu',damage:'Hư hỏng',saturation:'Bão hòa'})[k]);let fields=[[raw,'Rbefore'],[x.peak,'Rpeak'],[x.after,'Rafter']];let invalid=fields.filter(([v])=>val(v)&&!positive(v)).map(a=>a[1]),missing=fields.filter(([v])=>!val(v)).map(a=>a[1]);let status=invalid.length?'Không hợp lệ':flags.length?'Có bất thường':missing.length?'Chưa đủ':'Hợp lệ';return {b,dr,rec,drift,r:dr/b,status,reason:invalid.length?'Cần số dương hữu hạn: '+invalid.join(', '):flags.length?flags.join('; '):missing.length?'Thiếu: '+missing.join(', '):'Đủ số đo hợp lệ; chưa kết luận chất lượng cảm biến.'}}
function missingTN1(s){return ['step1','peak','wait'].filter(k=>!positive(state.settings[k])).map(k=>labels[k]).concat(!positive(s.r0)?['Điện trở không tải TN1']:[])}
function addCycle(){let s=sample(),d=+state.settings.step1,f=s.tn1.length?(+s.tn1.at(-1).f+d):d;let missing=missingTN1(s);if(missing.length)return alert('Thiếu: '+missing.join('; '));if(val(state.settings.safe)&&(!positive(state.settings.safe)||f>+state.settings.safe+1e-9))return alert('Kiểm tra giới hạn tải an toàn.');if(s.tn1.length){let m=tn1metrics(s.tn1.at(-1),s.tn1.length-1,s);if(m.status!=='Hợp lệ'&&m.status!=='Có bất thường')return alert('Kiểm tra chu kỳ trước: '+m.reason)}s.tn1.push({f,conditions:{step1:d,peak:state.settings.peak,wait:state.settings.wait,safe:state.settings.safe,r0:s.r0},before:s.tn1.length?s.tn1.at(-1).after:(s.r0)});save();stage=1;render()}
function tn1Plots(){let s=sample();let metrics=s.tn1.map((x,i)=>({f:+x.f,...tn1metrics(x,i,s)}));let out=`<section><h2>TN1 · Kết quả đo theo lực</h2><div class="bar"><select onchange="di=+this.value;render()">${ids.map((id,i)=>`<option value="${i}" ${di===i?'selected':''}>${id}</option>`).join('')}</select><select onchange="si=+this.value;render()">${[1,2,3].map(n=>`<option ${si===n?'selected':''}>${n}</option>`).join('')}</select></div><p>Chỉ hiển thị số liệu đo được. Ngưỡng phát hiện và dải đo được xác định sau khi xem xét đồ thị cùng độ phân giải và nhiễu thiết bị.</p>`;for(let [k,label] of [['dr','ΔR (Ω)'],['r','ΔR/Rbefore (%)'],['rec','Sai lệch phục hồi (%)'],['drift','Drift (%)']]){let p=metrics.filter(x=>Number.isFinite(x.f)&&Number.isFinite(x[k])).map(x=>[x.f,x[k]*(k==='r'?100:1)]);if(!p.length){out+=`<p>${label}: chưa có dữ liệu.</p>`;continue}let xmax=Math.max(...p.map(x=>x[0]),1e-9),lo=Math.min(0,...p.map(x=>x[1])),hi=Math.max(0,...p.map(x=>x[1]));if(hi===lo)hi=lo+1;let X=x=>65+350*x/xmax,Y=y=>190-150*(y-lo)/(hi-lo);out+=`<h3>${label}</h3><svg viewBox="0 0 460 230" style="width:100%;max-width:720px" role="img" aria-label="${label} theo lực"><path d="M65 30 V190 H415" fill="none" stroke="#334155"/>${[0,1,2,3,4].map(i=>`<text x="60" y="${Y(lo+(hi-lo)*i/4)+4}" text-anchor="end" font-size="10">${fmt(lo+(hi-lo)*i/4)}</text><path d="M65 ${Y(lo+(hi-lo)*i/4)} H415" stroke="#cbd5e1"/>`).join('')}${p.map(([x,y])=>`<circle cx="${X(x)}" cy="${Y(y)}" r="4" fill="#176b62"><title>F=${fmt(x)} N; ${label}=${fmt(y)}</title></circle>`).join('')}<polyline points="${p.map(([x,y])=>X(x)+','+Y(y)).join(' ')}" fill="none" stroke="#176b62"/><text x="65" y="210" font-size="11">0</text><text x="415" y="210" text-anchor="end" font-size="11">${fmt(xmax)} N</text><text x="240" y="225" text-anchor="middle" font-size="11">F danh nghĩa</text></svg>`}return out+'</section>'}
function lab(){let s=sample(),p=protocols[test];stage=Math.min(stage,p.length-1);let current=p[stage],checks=['Đúng mã mẫu','Mẫu và điện cực nguyên vẹn','Đồng hồ lực đã zero','Đầu nén đúng vị trí','Điều kiện đo đã thống nhất'];s.checks??={};let ck=s.checks[test]??=[];let h=`<section><div class="eyebrow">TRẠM THỰC NGHIỆM · ${key()}</div><div class="bar"><select aria-label="Cấu hình" onchange="di=+this.value;stage=0;render()">${ids.map((id,i)=>`<option value="${i}" ${di===i?'selected':''}>${id}</option>`).join('')}</select><select aria-label="Mẫu" onchange="si=+this.value;stage=0;render()">${[1,2,3].map(n=>`<option ${si===n?'selected':''}>${n}</option>`).join('')}</select><label><input type="checkbox" ${s.made?'checked':''} onchange="set('made',this.checked)"> Đã chế tạo</label>${['TN0','TN1','TN2'].map((t,i)=>`<button class="${test===i?'primary':''}" onclick="test=${i};stage=0;render()">${t}</button>`).join('')}</div><details ${test===1&&missingTN1(s).some(k=>k!=='Điện trở không tải TN1')?'open':''}><summary>Điều kiện đo dùng chung (21 mẫu)</summary>${Object.entries(labels).filter(([k])=>!['detect','recover','drift','fl','fu','step2'].includes(k)).map(([k,v])=>field(v,state.settings[k],`setting('${k}',this.value)`,hints[k])).join('')}<small>Không thay đổi điều kiện giữa các phép đo nếu chưa ghi nhận lý do. Lực TN1 mới được lưu cố định theo từng chu kỳ.</small></details></section><div class="labgrid"><section class="guide"><div class="eyebrow">HƯỚNG DẪN · ${stage+1}/${p.length}</div><h2>${['Điện trở ban đầu','Xác định dải đo','Đường đặc tính'][test]}</h2><p>${['Đo R₀ của 21 mẫu để so sánh và hồi quy ρ, Rp.','Thu thập đáp ứng điện trở theo lực và ghi nhận bất thường để phân tích dải đo sau.','Đo hai nhánh để tính độ nhạy, độ trễ và độ tuyến tính.'][test]}</p>${diagram()}<div class="stagebar">${p.map((_,i)=>`<button class="${i===stage?'primary':''}" onclick="setStage(${i})">${i+1}</button>`).join('')}</div><div class="step"><h2>${current[0]}</h2><p>${current[1]}</p><small><b>Ý nghĩa:</b> ${current[2]}</small></div><div class="bar"><button ${stage===0?'disabled':''} onclick="setStage(stage-1)">← Trước</button><button ${stage===p.length-1?'disabled':''} onclick="setStage(stage+1)">Tiếp →</button></div><details ${stage===0?'open':''}><summary>Checklist chuẩn bị (${ck.filter(Boolean).length}/5)</summary><div class="checklist">${checks.map((v,i)=>`<label><input type="checkbox" ${ck[i]?'checked':''} onchange="sample().checks[test]??=[];sample().checks[test][${i}]=this.checked;save();render()">${v}</label>`).join('')}</div></details><details><summary>Thời gian giữ tải / phục hồi</summary><div class="bar"><button onclick="startTimer('peak')">Giữ tải</button><button onclick="startTimer('wait')">Phục hồi</button><strong id="clock">—</strong></div></details></section><section><div class="eyebrow">DỮ LIỆU ĐO · TỰ LƯU CỤC BỘ</div>`;
if(test===0)h+=`<h2>Điện trở không tải</h2>${field('R₀ (Ω)',s.r0,"set('r0',this.value)",'Điện trở ổn định khi F = 0 N. Giá trị đo, không phải danh nghĩa; > 0 Ω.')}<div class="result">${val(s.r0)&&+s.r0>0?'Đã ghi nhận R₀':'Chờ giá trị điện trở dương'}</div><details><summary>R₀ được dùng để làm gì?</summary><svg viewBox="0 0 340 180" style="width:100%"><path d="M45 10 V145 H330" stroke="#334155" fill="none"/><path d="M45 120 L305 25" stroke="#2563eb" stroke-width="2"/><path d="M130 89 H240 V49" stroke="#64748b" stroke-dasharray="4 3" fill="none"/><g font-size="12" fill="#17365d"><text x="4" y="15">R₀ (Ω)</text><text x="12" y="124">Rp</text><text x="190" y="108">Độ dốc ρ</text><text x="220" y="164">Lc/A₀ (m⁻¹)</text><text x="85" y="35">R₀ = ρ Lc/A₀ + Rp</text></g></svg><small>Hồi quy 21 mẫu; giả định Rp chung và kích thước danh nghĩa. Hình minh họa.</small></details>`;
if(test===1){let i=s.tn1.length-1,x=s.tn1[i],m=x&&tn1metrics(x,i,s);h+=`<h2>Chu kỳ nén – nhả</h2>${baseline(s)}<div class="notice">Điều kiện chung: ΔF = ${esc(state.settings.step1||'—')} N · Giữ tải ${esc(state.settings.peak||'—')} s · Phục hồi ${esc(state.settings.wait||'—')} s.<br><small>Thiết lập một lần trong mục Điều kiện đo dùng chung phía trên.</small></div><small>${missingTN1(s).length?'Cần bổ sung: '+missingTN1(s).join('; '):'Có thể ghi nhận chu kỳ mới.'}</small><button class="primary" ${missingTN1(s).length?'disabled':''} onclick="addCycle()">+ Chu kỳ tải mới</button>`;if(x){h+=`<div class="result"><small>Chu kỳ ${i+1} · lực danh nghĩa</small><br><strong>${fmt(val(x.f)?+x.f:(i+1)*+state.settings.step1)} N</strong></div><details><summary>Đo lại Rbefore nếu gián đoạn</summary>${field('Rbefore (Ω)',x.before,`cell('tn1',${i},'before',this.value);render()`,'Chỉ sửa nếu đo lại tại F = 0 N; > 0 Ω.')}</details>${field('Rpeak (Ω)',x.peak,`cell('tn1',${i},'peak',this.value);render()`,'Đọc cuối thời gian giữ tải; > 0 Ω. Nếu mất tín hiệu, đánh dấu bất thường.')}${field('Rafter (Ω)',x.after,`cell('tn1',${i},'after',this.value);render()`,'Đọc tại F = 0 N sau thời gian phục hồi; > 0 Ω.')}${['loss','damage','saturation'].map((k,j)=>`<label><input type="checkbox" ${x[k]?'checked':''} onchange="cell('tn1',${i},'${k}',this.checked);render()">${['Mất tín hiệu','Hư hỏng','Bão hòa'][j]}</label>`).join('')}${field('Ghi chú',x.note,`cell('tn1',${i},'note',this.value)`,'Ghi lý do gián đoạn hoặc bất thường.','text')}<div class="result">${m?`<b>${m.status}</b><small style="display:block">${esc(m.reason)}</small><p>ΔR = ${fmt(m.dr)} Ω · r = ${fmt(m.r*100)}%</p><p>Phục hồi: ${fmt(m.rec)}% · Drift: ${fmt(m.drift)}%</p>`:'Chờ đủ dữ liệu đo'}</div>`}h+=`<details open><summary>Lịch sử chu kỳ (${s.tn1.length})</summary><div class="scroll"><table><tr><th>F (N)</th><th>Rpeak (Ω)</th><th>Rafter (Ω)</th><th>Giữ / phục hồi (s)</th><th>Trạng thái</th></tr>${s.tn1.map((x,i)=>`<tr><td>${fmt(val(x.f)?+x.f:(i+1)*+state.settings.step1)}</td><td>${esc(x.peak)}</td><td>${esc(x.after)}</td><td>${esc(x.conditions?.peak??'—')} / ${esc(x.conditions?.wait??'—')}</td><td>${tn1metrics(x,i,s).status}<small style="display:block">${esc(tn1metrics(x,i,s).reason)}</small></td></tr>`).join('')}</table></div></details><div class="statuslegend"><h3>Chú giải trạng thái</h3><table><tr><th>Trạng thái</th><th>Ý nghĩa / thao tác</th></tr><tr><td>Chưa đủ</td><td>Thiếu số đo; bổ sung nếu đo được.</td></tr><tr><td>Không hợp lệ</td><td>Giá trị điện trở không phải số dương hữu hạn.</td></tr><tr><td>Hợp lệ</td><td>Đủ số đo đúng định dạng; không đồng nghĩa cảm biến đạt yêu cầu.</td></tr><tr><td>Có bất thường</td><td>Ghi nhận mất tín hiệu, hư hỏng hoặc bão hòa; kiểm tra trước khi tiếp tục.</td></tr></table></div><details open><summary>Thời điểm đo và ý nghĩa chỉ tiêu</summary><svg viewBox="0 0 440 180" role="img" aria-label="Thời gian giữ tải và phục hồi"><path d="M40 10 V75 H425 M40 95 V155 H425" stroke="#334155" fill="none"/><path d="M40 75 H80 L110 25 H220 L240 75 H420" stroke="#2563eb" stroke-width="2" fill="none"/><path d="M40 145 H80 Q100 110 130 105 H220 Q240 140 300 143 H420" stroke="#176b62" stroke-width="2" fill="none"/><path d="M110 15 V155 M220 15 V155 M240 15 V155 M380 15 V155" stroke="#94a3b8" stroke-dasharray="4 3"/><g font-size="11" fill="#182b3e"><text x="4" y="15">F (N)</text><text x="4" y="100">R (Ω)</text><text x="165" y="19" text-anchor="middle">← t_hold →</text><text x="310" y="65" text-anchor="middle">← t_rec →</text><text x="220" y="99" text-anchor="end">Rpeak</text><text x="380" y="137" text-anchor="middle">Rafter</text><text x="75" y="137" text-anchor="middle">Rbefore</text><text x="410" y="170">t</text></g><circle cx="220" cy="105" r="4" fill="#d97706"/><circle cx="380" cy="143" r="4" fill="#176b62"/></svg><small>Đo Rpeak cuối giữ tải; bắt đầu phục hồi khi F = 0. Hình minh họa.</small><svg viewBox="0 0 540 300" style="width:100%;max-width:720px" role="img" aria-label="Biên độ tín hiệu và phục hồi"><g font-family="Arial" font-size="12" fill="#17365d"><path d="M55 25 V240 H515" fill="none" stroke="#334155"/><text x="15" y="17">R (Ω)</text><text x="515" y="258" text-anchor="end">t (s)</text><path d="M60 180 H90 C110 180 120 65 165 65 H255 C275 65 280 160 335 160 H385" fill="none" stroke="#2563eb" stroke-width="2.5"/><path d="M385 160 H465 M395 180 H465 M265 65 H465 M55 210 H385" stroke="#94a3b8" stroke-dasharray="4 4" fill="none"/><circle cx="90" cy="180" r="4" fill="#2563eb"/><circle cx="255" cy="65" r="4" fill="#d97706"/><circle cx="385" cy="160" r="4" fill="#16836b"/><text x="65" y="167">Rbefore</text><text x="255" y="50" text-anchor="middle">Rpeak</text><text x="385" y="145" text-anchor="middle">Rafter</text><text x="60" y="225">R₀ TN0</text><path d="M465 65 V180 M460 73 L465 65 L470 73 M460 172 L465 180 L470 172" fill="none" stroke="#d97706"/><text x="477" y="125" fill="#b45309">ΔR</text><path d="M410 160 V180 M405 160 H415 M405 180 H415" stroke="#16836b" fill="none"/><text x="420" y="197" fill="#16836b">Δrec</text><text x="55" y="280">ΔR = Rpeak − Rbefore</text><text x="300" y="280">Δrec = |Rafter − Rbefore|</text></g></svg><small>Minh họa, không phải số liệu đo. Phục hồi và drift biểu diễn theo % (nhân 100). Không áp dụng ngưỡng đạt/không đạt tại bước nhập liệu.</small></details>`}
if(test===2)h+=tn2entry(s);
return h+'</section></div>'}
let tab25=0,modules25=[];state.comments??={};
function baseline(s){return `<div class="result"><small>R₀ tham chiếu · TN0 · ${key()}</small><br><strong>${positive(s.r0)?fmt(+s.r0)+' Ω':'Chưa có R₀ hợp lệ'}</strong><p>${positive(s.r0)?'Tự động kế thừa từ TN0.':'Nhập R₀ tại TN0 trước khi đo.'}</p></div>`}
function ranges(){let a=all();if(!a.every(s=>val(s.fmin)&&val(s.fmax)&&+s.fmin>=0&&+s.fmax>=+s.fmin))return null;let l=Math.max(...a.map(s=>+s.fmin)),u=Math.min(...a.map(s=>+s.fmax));return u>l?[l,u]:null}
function tn2entry(s){let rg=ranges(),d=+state.settings.step2;return `<h2>Đặc tính nén / nhả</h2>${baseline(s)}<p>Dải chung: ${rg?rg.join(' – ')+' N':'Chưa xác định từ TN1'}</p>${field('Bước tải TN2 (N)',state.settings.step2,"setting('step2',this.value)",'Thiết lập một lần cho toàn bộ mẫu; > 0 N.')}<button class="primary" ${rg&&positive(d)&&positive(s.r0)&&!s.tn2.length?'':'disabled'} onclick="init2()">Tạo dãy tải nén – nhả</button><p class="muted">Chỉ nhập điện trở tại mỗi bậc; không nhả về zero giữa các bậc.</p>${tbl(['Nhánh','F (N)','R đo (Ω)'],s.tn2.map((x,i)=>[esc(x.branch||'Nén'),esc(x.f),`<input type="number" min="0" step="any" value="${esc(x.r)}" onchange="cell('tn2',${i},'r',this.value);render()"><small>${x.r==null||x.r===''?'Chưa đo':positive(x.r)?'Hợp lệ':'Không hợp lệ'}</small>`]),true)}${field('R sau phục hồi TN2 (Ω)',s.after2,"set('after2',this.value)",'Đo sau khi nhả hoàn toàn và chờ phục hồi; > 0 Ω.')}`}
function init2(){let rg=ranges(),d=+state.settings.step2,s=sample();if(!rg||!positive(d)||!positive(s.r0)||s.tn2.length)return;let [l,u]=rg;if((u-l)/d>99)return alert('Tối đa 100 điểm mỗi nhánh.');let a=[l];for(let f=l+d;f<u-1e-9;f+=d)a.push(+f.toFixed(9));a.push(u);s.tn2=[...a.map(f=>({f,branch:'Nén'})),...a.slice().reverse().map(f=>({f,branch:'Nhả'}))];save();render()}
function tbl(h,rows,raw=false){return `<div class="scroll"><table><thead><tr>${h.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${raw?x:esc(typeof x==='number'?fmt(x):x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function fit(p){if(p.length<2)return null;let n=p.length,x=p.reduce((a,b)=>a+b[0],0)/n,y=p.reduce((a,b)=>a+b[1],0)/n,xx=p.reduce((a,b)=>a+(b[0]-x)**2,0);if(!xx)return null;let m=p.reduce((a,b)=>a+(b[0]-x)*(b[1]-y),0)/xx,b=y-m*x,e=p.map(v=>v[1]-m*v[0]-b),ss=e.reduce((a,v)=>a+v*v,0),tot=p.reduce((a,v)=>a+(v[1]-y)**2,0);return {m,b,r2:tot?1-ss/tot:NaN,rmse:Math.sqrt(ss/n),e}}
function plot25(series,xlab,ylab){let colors=['#176b62','#c27818','#315777','#8a559f','#b34b54','#607487','#1688a0'],p=series.flatMap(s=>s.p).filter(v=>v.every(Number.isFinite));if(!p.length)return '<p class="muted">Chưa có dữ liệu hợp lệ để dựng đồ thị.</p>';let xmin=Math.min(...p.map(v=>v[0])),xmax=Math.max(...p.map(v=>v[0])),ymin=Math.min(...p.map(v=>v[1])),ymax=Math.max(...p.map(v=>v[1]));if(xmin===xmax){xmin-=.5;xmax+=.5}if(ymin===ymax){ymin-=.5;ymax+=.5}let X=x=>85+410*(x-xmin)/(xmax-xmin),Y=y=>245-195*(y-ymin)/(ymax-ymin);return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 540 ${310+series.length*18}" role="img" aria-label="${esc(ylab)} theo ${esc(xlab)}"><rect width="100%" height="100%" fill="white"/><g font-family="Arial" font-size="11" fill="#182b3e">${Array.from({length:5},(_,i)=>{let x=xmin+(xmax-xmin)*i/4,y=ymin+(ymax-ymin)*i/4;return `<path d="M85 ${Y(y)} H495" stroke="#e2e8f0"/><text x="77" y="${Y(y)+4}" text-anchor="end">${fmt(y)}</text><text x="${X(x)}" y="263" text-anchor="middle">${fmt(x)}</text>`}).join('')}<path d="M85 50 V245 H495" stroke="#334155" fill="none"/><text x="85" y="22">${esc(ylab)}</text><text x="290" y="286" text-anchor="middle">${esc(xlab)}</text>${series.map((s,i)=>{let c=colors[i%colors.length],q=s.p.filter(v=>v.every(Number.isFinite));return `${s.scatter?'':`<polyline points="${q.map(v=>X(v[0])+','+Y(v[1])).join(' ')}" fill="none" stroke="${c}" stroke-width="2" ${s.dash?'stroke-dasharray="5 4"':''}/>`}${s.dash?'':q.map(v=>`<circle cx="${X(v[0])}" cy="${Y(v[1])}" r="3" fill="${c}"/>`).join('')}<path d="M85 ${306+i*18} h20" stroke="${c}" stroke-width="2"/><text x="113" y="${310+i*18}">${esc(s.name)}</text>`}).join('')}</g></svg>`}
function module25(id,title,method,coeff,h,rows,series,x,y,note){let chart=plot25(series,x,y);modules25.push({id,title,method,coeff,h,rows,chart,note});return `<section class="module25" id="mod-${id}"><h2>${title}</h2><h3>Phương pháp phân tích</h3><p>${method}</p>${tbl(['Ký hiệu','Đơn vị','Nguồn / cách tính','Ý nghĩa hệ số','Giá trị'],coeff)}<h3>Bảng giá trị và đồ thị tương ứng</h3><div class="pair25">${tbl(h,rows)}<div>${chart}</div></div><h3>Nhận xét tự động</h3><p>${esc(note)}</p><label style="width:100%">Thảo luận của người nghiên cứu<textarea onchange="state.comments['${id}']=this.value;save()">${esc(state.comments[id]||'')}</textarea></label><div class="bar"><button onclick="export25('${id}','csv')">Bảng CSV</button><button onclick="export25('${id}','svg')">Đồ thị SVG</button><button onclick="export25('${id}','png')">Đồ thị PNG</button><button onclick="export25('${id}','txt')">Phương pháp / hệ số / nhận xét</button><button onclick="export25('${id}','html')">Toàn bộ module</button></div></section>`}
function tn2calc(s){let rg=ranges();if(!rg||!positive(s.r0))return null;let [l,u]=rg;let p=b=>s.tn2.filter(v=>(v.branch||'Nén')===b&&val(v.f)&&positive(v.r)&&+v.f>=l&&+v.f<=u).map(v=>[+v.f,100*(+v.r-+s.r0)/+s.r0]).sort((a,b)=>a[0]-b[0]);let a=p('Nén'),b=p('Nhả');if(a.length<2||b.length<2||a[0][0]!==l||a.at(-1)[0]!==u||b[0][0]!==l||b.at(-1)[0]!==u||a.length!==b.length||a.some((v,i)=>v[0]!==b[i][0]||(i&&v[0]===a[i-1][0])))return null;let f=fit(a),fs=Math.max(...a.map(v=>v[1]))-Math.min(...a.map(v=>v[1]));return {a,b,f,k:f.m,abs:f.m*+s.r0/100,h:fs?100*Math.max(...a.map((v,i)=>Math.abs(v[1]-b[i][1])))/fs:NaN,nl:fs?100*Math.max(...f.e.map(Math.abs))/fs:NaN,local:a.slice(1).map((v,i)=>[(v[0]+a[i][0])/2,(v[1]-a[i][1])/(v[0]-a[i][0])])}}
