function rangeSet(k,v){let s=sample();if(v!==''&&(!val(v)||+v<0||!s.tn1.some((x,i)=>+x.f===+v&&tn1metrics(x,i,s).status==='Hợp lệ')))return alert('Chọn mức lực đã đo hợp lệ.');if(v!==''&&((k==='fmin'&&val(s.fmax)&&+v>+s.fmax)||(k==='fmax'&&val(s.fmin)&&+v<+s.fmin)))return alert('Fmin phải ≤ Fmax.');set(k,v)}
