function csv25(rows){return '\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n')}
function report25(m){return `<h2>${esc(m.title)}</h2><p>${esc(m.method)}</p>${tbl(['Ký hiệu','Đơn vị','Nguồn / cách tính','Ý nghĩa hệ số','Giá trị'],m.coeff)}<div class="pair25">${tbl(m.h,m.rows)}${m.chart}</div><h3>Nhận xét</h3><p>${esc(m.note)}</p><p>${esc(state.comments[m.id]||'')}</p>`}
function export25(id,type){let m=modules25.find(v=>v.id===id);if(!m)return;if(type==='csv')return dl25(id+'.csv',csv25([m.h,...m.rows]),'text/csv');if(type==='txt')return dl25(id+'.txt',[m.title,m.method,...m.coeff.map(r=>r.join(' | ')),m.note,state.comments[id]||''].join('\n'),'text/plain');if(type==='html')return dl25(id+'.html',reportDoc(report25(m)),'text/html');let svg=m.chart;if(!svg.startsWith('<svg'))return alert('Chưa có đồ thị.');if(type==='svg')return dl25(id+'.svg',svg,'image/svg+xml');let im=new Image();let url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));im.onload=()=>{let c=document.createElement('canvas');c.width=1620;c.height=im.height/im.width*1620;c.getContext('2d').drawImage(im,0,0,c.width,c.height);let a=document.createElement('a');a.href=c.toDataURL('image/png');a.download=id+'.png';a.click();URL.revokeObjectURL(url)};im.src=url}
function reportDoc(h){return '<!doctype html><meta charset="utf-8"><style>body{font:14px Arial;color:#182b3e;margin:30px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #aaa;padding:7px;overflow-wrap:anywhere}th{background:#eaf0f5}.pair25{display:grid;grid-template-columns:1fr 1fr;gap:16px}svg{width:100%}h2{margin-top:35px}@media print{h2{break-after:avoid}}svg text{font-family:Arial,sans-serif}.pair25{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;align-items:start}.pair25 .scroll{max-height:420px}.module25{border-top:3px solid #176b62}.module25 h3{font-size:15px}.module25 textarea{width:100%;font:inherit;border:1px solid #bdcbd8;padding:10px;border-radius:6px}.module25 td:last-child{text-align:left}.module25 svg{background:white}.subnav{position:sticky;top:0;background:#f4f6f8;padding:10px 0;z-index:2}@media(max-width:1100px){.pair25{grid-template-columns:1fr}}@media print{aside,.subnav,button,.notice{display:none!important}main{margin:0;padding:0}.scroll{max-height:none!important;overflow:visible}.module25{break-inside:avoid}body{background:white}} </style>'+h}
function exportAll25(){let old=tab25,body='';for(let i=0;i<4;i++){tab25=i;analysis25();body+=modules25.map(report25).join('')}tab25=old;fem25();body+=modules25.map(report25).join('');dl25('CAPSTONE_report.html',reportDoc(body),'text/html');render()}
function exportCenter(){return `<section><h2>Research Export Center</h2><p>Xuất riêng từng module tại trang Phân tích hoặc COMSOL. Báo cáo HTML có bảng, đồ thị, phương pháp, hệ số và nhận xét; mở bằng trình duyệt để in PDF.</p><div class="bar"><button class="primary" onclick="exportAll25()">Xuất báo cáo HTML</button><button onclick="download()">Sao lưu toàn bộ JSON</button><button onclick="dl25('geometry.svg',geom(di).replace('<svg ','<svg xmlns=&quot;http://www.w3.org/2000/svg&quot; '),'image/svg+xml')">Hình kỹ thuật SVG</button></div><label>Khôi phục JSON<input type="file" accept=".json" onchange="restore25(this.files[0])"></label><p class="muted">XLSX, DOCX, ZIP và đồng bộ máy chủ chưa triển khai.</p></section>`}
async function restore25(file){if(!file)return;try{let v=JSON.parse(await file.text());if(!v.samples||!v.settings||!v.mesh)throw Error();if(!confirm('Thay thế dữ liệu hiện tại bằng bản sao lưu?'))return;state=v;state.comments??={};save();render()}catch(e){alert('Bản sao lưu không hợp lệ.')}}

