function aggregateCurves26(t,groups,names,prefix,internal=false){let h='';let specs=t===1?[['Biên độ tín hiệu','ΔR (Ω)','Rpeak − Rbefore'],['Tín hiệu tương đối','r (%)','100 ΔR/Rbefore'],['Sai lệch phục hồi','εrec (%)','100 |Rafter−Rbefore|/Rbefore'],['Drift','εdrift (%)','100 |Rafter−R₀|/R₀'],['Điện trở trước tải','Rbefore (Ω)','Mốc trước chu kỳ'],['Điện trở đỉnh','Rpeak (Ω)','Đo cuối giữ tải'],['Điện trở sau tải','Rafter (Ω)','Đo sau phục hồi']]:[['Nhánh nén','%','100(R−R₀)/R₀'],['Nhánh nhả','%','100(R−R₀)/R₀'],['Độ nhạy cục bộ','%/N','Δr/ΔF'],['Chênh lệch nén – nhả','r','|r_nén−r_nhả|'],['Phần dư hồi quy','r','r−(KF·F+b)']];specs.forEach(([title,unit,method],j)=>{let get=s=>{if(t===1)return points26(s,j);let z=tn2calc(s);if(!z)return [];return [z.a,z.b,z.local,z.a.map((v,i)=>[v[0],Math.abs(v[1]-z.b[i][1])]),z.a.map((v,i)=>[v[0],z.f.e[i]])][j]};let sets=groups.map((g,i)=>({name:names[i],p:common26(g.map(get))}));if(internal){sets=[...groups[0].map((s,i)=>({name:'S0'+(i+1),p:get(s)})),...sets];}h+=curveModule26(prefix+j,'TN'+t+' — '+title,unit,method+'; trung bình tại cùng lực, đủ 3 mẫu, không ngoại suy.',title,sets,internal)});return h}
function summary26(groups,names,prefix){let h='';let metrics=[['KF','%/N',z=>z.k,'Độ dốc OLS nhánh nén'],['Kabs','Ω/N',z=>z.abs,'KF × R₀/100'],['H','% FS',z=>z.h,'100 max|r_nén−r_nhả|/FS'],['NL','% FS',z=>z.nl,'100 max|phần dư|/FS'],['R²','—',z=>z.f.r2,'1−SSE/SST'],['RMSE','điểm %',z=>z.f.rmse,'√mean(e²)']];for(let [k,u,get,m] of metrics){let rows=groups.map((g,i)=>{let q=g.map(s=>{let z=tn2calc(s);return z?get(z):NaN});return [names[i],...q,q.every(Number.isFinite)?mean(q):NaN,q.every(Number.isFinite)?sd(q):NaN]});h+=module25(prefix+k,'TN2 — '+k,m+'; FS = max(r_nén)−min(r_nén).',[ [k,u,m,({KF:'Độ nhạy tương đối',Kabs:'Độ nhạy tuyệt đối',H:'Phụ thuộc lịch sử tải',NL:'Sai lệch tuyến tính','R²':'Tỷ lệ biến thiên giải thích',RMSE:'Sai lệch điển hình'})[k],''] ],['Cấu hình','S01','S02','S03','Mean','SD'],rows,[{name:k+' Mean ± SD',p:rows.map((r,i)=>[i+1,r[4],r[5]]),scatter:true}],'Cấu hình (1–7)',k+' ('+u+')','Chỉ tổng hợp đủ ba mẫu; SD giữa mẫu.')}return h}
