const cache27=new Map(), names27=['Tuyến tính','Bậc 2','Bậc 3','Logarit','Hàm mũ'];
function ls27(p,d){let n=d+1,A=Array.from({length:n},(_,i)=>Array.from({length:n+1},(_,j)=>p.reduce((s,[x,y])=>s+x**i*(j===n?y:x**j),0)));for(let i=0;i<n;i++){let k=i;for(let j=i+1;j<n;j++)if(Math.abs(A[j][i])>Math.abs(A[k][i]))k=j;[A[i],A[k]]=[A[k],A[i]];let v=A[i][i];if(Math.abs(v)<1e-12)return null;A[i]=A[i].map(x=>x/v);for(let j=0;j<n;j++)if(j!==i){let q=A[j][i];A[j]=A[j].map((x,k)=>x-q*A[i][k])}}return A.map(r=>r[n])}
function model27(p,i){let k=i<3?i+2:3,n=p.length;if(n<=k||new Set(p.map(v=>v[0])).size<k)return null;let max=Math.max(...p.map(v=>Math.abs(v[0])))||1,a,f,der,eq; if(i<3){let q=ls27(p.map(([x,y])=>[x/max,y]),i+1);if(!q)return null;a=q.map((v,j)=>v/max**j);f=x=>a.reduce((s,v,j)=>s+v*x**j,0);der=x=>a.slice(1).reduce((s,v,j)=>s+(j+1)*v*x**j,0);eq=a.map((v,j)=>`${v.toPrecision(7)}${j?' F'+(j>1?'^'+j:''):''}`).join(' + ')}else{let best=null;function trial(b){let g=x=>i===3?Math.log1p(b*x):Math.expm1(b*x);let q=p.map(([x,y])=>[g(x),y]);if(q.some(v=>!Number.isFinite(v[0])))return;let z=fit(q);if(!z||!Number.isFinite(z.rmse))return;if(!best||z.rmse<best.err)best={b,a:z.m,c:z.b,err:z.rmse}}let lo=i===3?-.999/max:-20/max,hi=20/max;for(let j=0;j<=240;j++)trial(lo+(hi-lo)*j/240);for(let j=-6;j<=1;j+=.1){trial(10**j/max);trial(-(10**j)/max)}if(!best)return null;let step=(hi-lo)/240;for(let j=0;j<35;j++){let b=best.b;trial(Math.max(lo,b-step));trial(Math.min(hi,b+step));step*=.65}let {a:u,b,c}=best;if(Math.abs(b*max)<1e-5||Math.abs(b-lo)<1e-7||Math.abs(b-hi)<1e-7)return null;a=[u,b,c];f=x=>u*(i===3?Math.log1p(b*x):Math.expm1(b*x))+c;der=x=>u*b*(i===3?1/(1+b*x):Math.exp(b*x));eq=`${u.toPrecision(7)} × ${i===3?'ln(1 + '+b.toPrecision(7)+' F)':'(exp('+b.toPrecision(7)+' F) − 1)'} + ${c.toPrecision(7)}`}
let e=p.map(([x,y])=>y-f(x)),sse=e.reduce((s,v)=>s+v*v,0),ys=p.map(v=>v[1]),avg=mean(ys),sst=ys.reduce((s,v)=>s+(v-avg)**2,0),fs=Math.max(...ys)-Math.min(...ys),r2=sst?1-sse/sst:NaN,rmse=Math.sqrt(sse/n),mae=mean(e.map(Math.abs)),mx=Math.max(...e.map(Math.abs)),K=k+1,base=n*Math.log(sse/n),l=Math.min(...p.map(v=>v[0])),u=Math.max(...p.map(v=>v[0])),grid=Array.from({length:101},(_,j)=>l+(u-l)*j/100);return {a,f,der,eq,e,grid,k,n,r2,adj:1-(1-r2)*(n-1)/(n-k),sse,mse:sse/n,rmse,mae,mx,nrmse:fs?100*rmse/fs:NaN,aicc:n>K+1&&sse>0?base+2*K+2*K*(K+1)/(n-K-1):NaN,bic:sse>0?base+K*Math.log(n):NaN,mono:grid.every(x=>der(x)>=-1e-9),nl:fs?100*mx/fs:NaN}}
