function plot27(series,x,y,scale='linear',locked=false){let colors=['#2563eb','#16836b','#b34b54','#8a559f','#c27818','#607487','#1688a0'],p=series.flatMap(s=>s.p).filter(v=>Number.isFinite(v[0])&&Number.isFinite(v[1]));if(!p.length)return '<p>Chưa có dữ liệu hợp lệ.</p>';let ext=p.flatMap(v=>Number.isFinite(v[2])?[v[1]-v[2],v[1]+v[2]]:[v[1]]),log=scale==='log'&&ext.every(v=>v>0),T=v=>log?Math.log10(v):v;let a=Math.min(...p.map(v=>v[0])),b=Math.max(...p.map(v=>v[0])),c=Math.min(...ext.map(T)),d=Math.max(...ext.map(T));if(!log&&scale!=='zoom'){c=Math.min(0,c);d=Math.max(0,d)}if(a===b){a-=.5;b+=.5}if(c===d){c-=.5;d+=.5}let X=v=>85+410*(v-a)/(b-a),Y=v=>245-195*(T(v)-c)/(d-c);return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 540 ${315+series.length*20}" role="img"><rect width="100%" height="100%" fill="white"/><g font-family="Arial" font-size="11" fill="#182b3e">${Array.from({length:5},(_,i)=>{let v=c+(d-c)*i/4,w=log?10**v:v;return `<path d="M85 ${Y(w)} H495" stroke="#e2e8f0"/><text x="77" y="${Y(w)+4}" text-anchor="end">${w.toPrecision(4)}</text><text x="${X(a+(b-a)*i/4)}" y="263" text-anchor="middle">${fmt(a+(b-a)*i/4)}</text>`}).join('')}<path d="M85 50 V245 H495" stroke="#334155" fill="none"/><text x="85" y="22">${esc(y)} · ${log?'log₁₀':scale==='zoom'?'vùng dữ liệu':'tuyến tính'}</text><text x="290" y="286" text-anchor="middle">${esc(x)}</text>${series.map((s,i)=>{let q=s.p.filter(v=>Number.isFinite(v[0])&&Number.isFinite(v[1])),col=colors[i%colors.length];return `${s.scatter?'':`<polyline points="${q.map(v=>X(v[0])+','+Y(v[1])).join(' ')}" stroke="${col}" fill="none" stroke-width="2" ${s.dash?'stroke-dasharray="5 4"':''}/>`}${q.map(v=>`${Number.isFinite(v[2])?`<path d="M${X(v[0])} ${Y(v[1]-v[2])} V${Y(v[1]+v[2])}" stroke="${col}"/>`:''}${s.dash?'':`<circle cx="${X(v[0])}" cy="${Y(v[1])}" r="3" fill="${col}"/>`}`).join('')}<path d="M85 ${306+i*20} h20" stroke="${col}"/><text x="113" y="${310+i*20}">${esc(s.name)}</text>`}).join('')}</g></svg>`}
