const oldCurve29=curveModule26;
curveModule26=function(id,title,unit,method,meaning,sets,internal=false){let sym=({'Biên độ tín hiệu':'ΔR_TN1','Tín hiệu tương đối':'r_TN1','Sai lệch phục hồi':'ε_rec','Drift':'ε_drift','Điện trở trước tải':'R_before','Điện trở đỉnh':'R_peak','Điện trở sau tải':'R_after','Nhánh nén':'r_L','Nhánh nhả':'r_U','Độ nhạy cục bộ':'K_local','Chênh lệch nén – nhả':'Δr_LU','Phần dư hồi quy':'e'})[meaning]||'r';let d=notation29[sym],u=d[1],rows=sets.flatMap(s=>s.p.map(v=>{let avg=!internal||!/^S0[123]$/.test(s.name);return [s.name,v[0],avg?null:v[1],avg?v[1]:null,avg?v[2]:null,avg&&Number.isFinite(v[2])&&v[1]!==0?100*v[2]/Math.abs(v[1]):null,avg?3:1]}));let h=['Cấu hình / mẫu','F (N)','Giá trị '+sym+' ('+u+')','Trung bình '+sym+' ('+u+')','SD ('+(u==='%'?'điểm %':u)+')','CV (%)','n'];if(!internal){h.splice(2,1);rows=rows.map(r=>r.filter((_,i)=>i!==2));h[0]='Cấu hình'}return module25(id,title,method,[[sym,u,d[2],d[3],''],['SD',u,'Độ lệch chuẩn mẫu (n−1)','Phân tán giữa mẫu',''],['CV','%','100 SD/|trung bình|','Phân tán tương đối; không xác định khi trung bình bằng 0',''],['n','1','Đếm mẫu','Số mẫu hợp lệ','']],h,rows,sets,'F (N)',sym+' ('+u+')',rows.length?'SD giữa mẫu, không phải sai số thiết bị. CV chỉ có ý nghĩa khi trung bình khác 0; thận trọng với phần dư gần 0.':'Chưa đủ dữ liệu.');};
const oldModule29=module25;
module25=function(id,title,method,coeff,h,rows,series,x,y,note){let map={signal:'ΔR_TN1',relative:'r_TN1',recovery:'ε_rec',drift:'ε_drift'};coeff=coeff.map(r=>{let k=map[r[0]]||rename29(r[0]);return [k,r[1]==='—'||r[1]==='r'?'1':r[1],rename29(r[2]),rename29(r[3]),r[4]]});h=h.map(rename29);if(id==='tn0summary')h=['Cấu hình','n','Trung bình R₀ (Ω)','SD_R₀ (Ω)','CV_R₀ (%)'];if(id==='tn1raw')h=['F (N)','R_before (Ω)','R_peak (Ω)','R_after (Ω)','Trạng thái'];if(id==='tn2')h=['F (N)','r_L (%)','r_U (%)','e (điểm %)'];if(id==='local')h=['F giữa khoảng (N)','K_local (%/N)'];if(id==='fem2'||id==='fem3'||id==='fem4')h=['Lưới',rename29(x),id==='fem4'?'R_FEM (Ω)':rename29(y)];let html=oldModule29(id,rename29(title),rename29(method),coeff,h,rows,series.map(s=>({...s,name:rename29(s.name)})),rename29(x),rename29(y),rename29(note));let m=modules25.find(v=>v.id===id);let cc=coeff.map(r=>[r[0],notation29[r[0]]?.[0]||names29[r[0]]||r[3],...r.slice(1)]);if(m){m.coeff=cc;m.coeffHeaders=['Ký hiệu','Tên đại lượng','Đơn vị','Nguồn / cách tính','Ý nghĩa','Giá trị']}let original=tbl(['Ký hiệu','Đơn vị','Nguồn / cách tính','Ý nghĩa hệ số','Giá trị'],coeff);return html.replace(original,cc.length?tbl(m?.coeffHeaders||['Ký hiệu','Tên đại lượng','Đơn vị','Nguồn / cách tính','Ý nghĩa','Giá trị'],cc):'').replace('Bảng giá trị và đồ thị tương ứng','Bảng kết quả — '+rename29(title)+' và đồ thị');};
const oldTbl29=tbl;tbl=function(h,rows,raw=false){return oldTbl29(h.map(rename29),rows,raw)};
