const mathMap291={R0:'R_0','R₀':'R_0',Rbefore:'R_{\\mathrm{before}}',Rpeak:'R_{\\mathrm{peak}}',Rafter:'R_{\\mathrm{after}}',Scenter:'S_{\\mathrm{center}}',Fmin:'F_{\\min}',Fmax:'F_{\\max}',KF:'K_F',Kabs:'K_{\\mathrm{abs}}',Klocal:'K_{\\mathrm{local}}',Rp:'R_p',Lc:'L_c',Ls:'L_s',Ws:'W_s',Hs:'H_s',wc:'w_c',hc:'h_c',tb:'t_b',tt:'t_t',Dp:'D_p',hp:'h_p',FL:'F_L',FU:'F_U','R²':'R^2','S₀':'S_0','A₀':'S_0','ΔR':'\\Delta R','ΔF':'\\Delta F','ρ':'\\rho','δ':'\\delta','εrec':'\\varepsilon_{\\mathrm{rec}}','εdrift':'\\varepsilon_{\\mathrm{drift}}','r_nén':'r_L','r_nhả':'r_U','a₀':'a_0','a₁':'a_1','a₂':'a_2','a₃':'a_3','F²':'F^2','F³':'F^3','mm²':'\\mathrm{mm}^2','m⁻¹':'\\mathrm{m}^{-1}','N⁻¹':'\\mathrm{N}^{-1}','Ω':'\\Omega'};
const mathToken291=/(?:\b(?:Rbefore|Rpeak|Rafter|Scenter|Fmin|Fmax|KF|Kabs|Klocal|Rp|Lc|Ls|Ws|Hs|wc|hc|tb|tt|Dp|hp|FL|FU|R0|a[0-3]|[A-Za-z]+_[A-Za-z0-9₀]+)\b|R²|R₀|S₀|A₀|ΔR|ΔF|ρ|δ|εrec|εdrift|r_nén|r_nhả|[aF][₀₁₂₃²³]|mm²|m⁻¹|N⁻¹|Ω|\b\d+(?:\.\d+)?e[+-]?\d+\b)/g;
function tex291(t){if(mathMap291[t])return mathMap291[t];if(/^\d.*e/i.test(t)){let [a,b]=t.split('e');return a+'\\times10^{'+Number(b)+'}'}let [a,b]=t.split('_');if(b)return a+'_{'+(b.length>1?'\\mathrm{'+b+'}':b)+'}';return t;}
function mathReady291(){return typeof MathJax?.tex2svg==='function'}
function svgMath291(tex){return MathJax.tex2svg(tex,{display:false}).querySelector('svg')}
function typeset291(root){if(!root||!mathReady291())return;let walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(let n of nodes){let p=n.parentElement;if(!p||p.closest('mjx-container,script,style,textarea,input,select,option,svg,[data-math291]'))continue;let t=n.nodeValue;mathToken291.lastIndex=0;if(!mathToken291.test(t))continue;mathToken291.lastIndex=0;let frag=document.createDocumentFragment(),last=0;for(let m of t.matchAll(mathToken291)){frag.append(t.slice(last,m.index));let span=document.createElement('span');span.dataset.math291='1';span.style.whiteSpace='nowrap';let rendered=MathJax.tex2svg(tex291(m[0]),{display:false});rendered.querySelectorAll("mjx-assistive-mml").forEach(e=>e.remove());span.append(rendered);frag.append(span);last=m.index+m[0].length}frag.append(t.slice(last));let line=document.createElement("span");line.dataset.math291="line";line.append(frag);n.replaceWith(line)}
for(let n of root.querySelectorAll('svg text')){if(n.closest('mjx-container')||n.dataset.math291)continue;let t=n.textContent;mathToken291.lastIndex=0;if(!mathToken291.test(t))continue;mathToken291.lastIndex=0;let parts=[],last=0;for(let m of t.matchAll(mathToken291)){if(m.index>last)parts.push('\\text{'+t.slice(last,m.index).replace(/[%{}]/g,'\\$&')+'}');parts.push(tex291(m[0]));last=m.index+m[0].length}if(last<t.length)parts.push('\\text{'+t.slice(last).replace(/[%{}]/g,'\\$&')+'}');try{let svg=svgMath291(parts.join(' ')),vb=svg.viewBox.baseVal,fs=Number(n.getAttribute('font-size')||n.parentElement.getAttribute('font-size')||11),w=vb.width*fs/1000,h=vb.height*fs/1000,x=Number(n.getAttribute('x')||0),y=Number(n.getAttribute('y')||0);if(!Number.isFinite(w)||!w)continue;let anchor=n.getAttribute('text-anchor');svg.setAttribute('x',x-(anchor==='middle'?w/2:anchor==='end'?w:0));svg.setAttribute('y',y+vb.y*fs/1000);svg.setAttribute('width',w);svg.setAttribute('height',h);svg.removeAttribute('style');svg.dataset.math291='1';if(n.hasAttribute('transform'))svg.setAttribute('transform',n.getAttribute('transform'));n.replaceWith(svg)}catch(e){console.warn('Math label',t,e)}}}
const render291=render;render=function(){render291();if(mathReady291())typeset291(document.querySelector('#view'));else MathJax.startup.promise.then(()=>typeset291(document.querySelector('#view')))};
const plot291=plot27;plot27=function(...args){let h=plot291(...args);if(!mathReady291()||!h.startsWith('<svg'))return h;let d=document.createElement('div');d.innerHTML=h;typeset291(d);return d.innerHTML};
const report291=reportDoc;reportDoc=function(h){let d=document.createElement('div');d.innerHTML=h;typeset291(d);return report291(d.innerHTML).replace("</head>",'<style>mjx-assistive-mml{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}span[data-math291],span[data-math291] mjx-container{display:inline!important;white-space:nowrap!important;margin:0!important}span[data-math291] svg{display:inline-block!important;max-width:none!important;vertical-align:middle}.field>span[data-math291]{display:inline!important}.num{overflow-wrap:normal;font-size:clamp(18px,2.2vw,30px)}.num mjx-container svg{max-width:100%!important}</style></head>')};

